package org.jlinalg.cli;

import java.io.*;
import java.util.*;
import java.util.stream.Stream;
import java.util.zip.GZIPInputStream;
import org.jlinalg.singlecell.SoupXAmbient;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import static org.junit.jupiter.api.Assertions.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

class SoupXAmbientTest {
    record Case(String version,Map<String,Object> value){@Override public String toString(){return version+":"+value.get("id");}}
    static Map<String,Object> fixture(String name)throws IOException{try(var stream=new GZIPInputStream(Objects.requireNonNull(SoupXAmbientTest.class.getResourceAsStream("/org/jlinalg/singlecell/soupx-ambient/"+name)))){return object(NextflowParameters.parse(NextflowFiles.utf8(stream.readAllBytes()),32<<20,3000000));}}
    static Stream<Case> cases(String prefix)throws IOException{var cases=new ArrayList<Case>();for(String v:List.of("1.6.2","1.3.0")){var root=fixture("original-"+v+"-v1.json.gz");assertEquals(Boolean.TRUE,root.get("source_bodies_and_formals_checked_before_and_after"));for(Object o:list(root.get("cases"))){var value=object(o);if(text(value.get("id")).startsWith(prefix))cases.add(new Case(v,value));}}return cases.stream();}
    static Stream<Case> profiles()throws IOException{return cases("profile-");}
    static Stream<Case> manual()throws IOException{return cases("manual-").filter(c->!c.value.get("id").equals("manual-no-accepted-cells"));}
    static SoupXAmbient.Counts counts(Object raw)throws IOException {var m=object(raw);var entries=new ArrayList<SoupXAmbient.Entry>();for(Object o:list(m.get("entries"))){var e=object(o);String token=text(e.get("value"));double n=Double.parseDouble(token);assertEquals(Math.rint(n),n);entries.add(new SoupXAmbient.Entry((int)integer(e.get("gene"),0,1000000),(int)integer(e.get("cell"),0,10000000),(long)n));}return new SoupXAmbient.Counts(strings(m.get("genes"),1000000),strings(m.get("cells"),10000000),entries,budget());}
    static SoupXAmbient.Budget budget(){return new SoupXAmbient.Budget(100000000);}
    static double number(Object o){return Double.parseDouble(o instanceof NextflowParameters.NumberToken t?t.text():o.toString());}
    static void close(double expected,double actual){if(!Double.isFinite(expected)||expected==0)assertEquals(expected,actual);else assertEquals(expected,actual,Math.max(64*Math.ulp(expected),3e-12*Math.abs(expected)));}
    @ParameterizedTest(name="{0}") @MethodSource("profiles") void matchesEveryOriginalSoupProfileGeneAndStrictDropletRange(Case c)throws IOException {
        var inputs=fixture("inputs-v1.json.gz");var raw=counts(inputs.get("raw"));var settings=object(c.value.get("settings"));var range=list(settings.get("soup_range"));var result=SoupXAmbient.profile(raw,number(range.get(0)),number(range.get(1)),budget());assertTrue(bool(c.value.get("returned")));assertEquals(strings(c.value.get("gene_ids"),1000000),result.genes());var rows=list(c.value.get("soup_profile"));assertEquals(rows.size(),result.counts().size());
        for(int i=0;i<rows.size();i++){var row=object(rows.get(i));close(number(row.get("counts")),result.counts().get(i));close(number(row.get("est")),result.fractions().get(i));}
        if(c.value.get("id").equals("profile-no-selected-droplets")){assertEquals(0,result.total());assertTrue(result.selectedDroplets().isEmpty());assertTrue(result.fractions().stream().allMatch(d->Double.isNaN(d)));}
    }
    @ParameterizedTest(name="{0}") @MethodSource("manual") void preservesMasksAndSeparatesAnalyticalMleFromOriginalGlm(Case c)throws IOException {
        var inputs=fixture("inputs-v1.json.gz");var raw=counts(inputs.get("raw"));var filtered=counts(inputs.get("filtered"));var profile=SoupXAmbient.profile(raw,0,100,budget());var sets=new LinkedHashMap<String,List<String>>();sets.put("CD7",List.of("CD7"));var groupMap=object(inputs.get("clusters"));var labels=new ArrayList<String>();for(String cell:filtered.cells())labels.add(text(groupMap.get(cell)));SoupXAmbient.Mask mask;
        if(c.value.get("id").equals("manual-supplied-mask")){var accepted=new ArrayList<List<Boolean>>();for(String label:labels)accepted.add(List.of(!label.equals(labels.get(0))));mask=new SoupXAmbient.Mask(filtered.cells(),List.of("CD7"),accepted,List.of());}
        else{boolean cellOnly=c.value.get("id").equals("manual-automatic-mask-cell-only");mask=SoupXAmbient.nonExpressing(filtered,profile,sets,cellOnly?null:labels,1,.05,1000000,budget());}
        assertTrue(bool(c.value.get("returned")));assertEquals(filtered.cells(),strings(c.value.get("nonexpressing_cells"),1000000));assertEquals(mask.geneSets(),strings(c.value.get("nonexpressing_groups"),1000000));var original=list(c.value.get("nonexpressing"));assertEquals(mask.accepted().size(),original.size());for(int i=0;i<original.size();i++){var row=list(original.get(i));assertEquals(mask.geneSets().size(),row.size());for(int j=0;j<row.size();j++)assertEquals(row.get(j),mask.accepted().get(i).get(j));}
        var fit=SoupXAmbient.globalPoisson(filtered,profile,sets,mask,budget());var diagnosis=object(object(object(fixture("poisson-diagnosis-v1.json.gz").get(c.version)).get("cases")).get(text(c.value.get("id"))));assertEquals((long)number(diagnosis.get("observed")),fit.observed());close(number(diagnosis.get("exposure")),fit.exposure());close(number(diagnosis.get("analytical_rho")),fit.rho());assertTrue(bool(diagnosis.get("original_converged")));double originalRho=number(diagnosis.get("original_rho"));assertTrue(Math.abs(originalRho-fit.rho())>1e-10*originalRho,"Original iterative GLM difference must remain explicit, not mislabeled as bitwise agreement");assertEquals(number(diagnosis.get("original_minus_analytical")),originalRho-fit.rho(),128*Math.ulp(originalRho));
        var metadata=list(c.value.get("channel_metadata"));assertEquals(filtered.cells(),strings(c.value.get("cell_ids"),1000000));for(Object o:metadata)close(number(object(o).get("rho")),originalRho);assertTrue(fit.acceptedCellSets()>0&&fit.observed()>0&&fit.exposure()>0);
    }
    @Test void verifiesOriginalRawSubsetRelationAndRefusesChangedValue()throws IOException {var inputs=fixture("inputs-v1.json.gz");var raw=counts(inputs.get("raw"));var filtered=counts(inputs.get("filtered"));if(bool(inputs.get("raw_subset_equal")))SoupXAmbient.verifyRawSubset(raw,filtered,budget());else assertThrows(IllegalArgumentException.class,()->SoupXAmbient.verifyRawSubset(raw,filtered,budget()));var changed=new ArrayList<>(filtered.entries());var first=changed.get(0);changed.set(0,new SoupXAmbient.Entry(first.gene(),first.cell(),first.count()+1));var altered=new SoupXAmbient.Counts(filtered.genes(),filtered.cells(),changed,budget());assertThrows(IllegalArgumentException.class,()->SoupXAmbient.verifyRawSubset(raw,altered,budget()));}
    @Test void refusesDuplicateCoordinatesNonexactCountsAndWorkOverflow(){assertThrows(IllegalArgumentException.class,()->new SoupXAmbient.Counts(List.of("g"),List.of("c"),List.of(new SoupXAmbient.Entry(0,0,1),new SoupXAmbient.Entry(0,0,0)),budget()));assertThrows(IllegalArgumentException.class,()->new SoupXAmbient.Counts(List.of("g"),List.of("c"),List.of(new SoupXAmbient.Entry(0,0,9007199254740992L)),budget()));assertThrows(IllegalArgumentException.class,()->new SoupXAmbient.Counts(List.of("g","h"),List.of("c"),List.of(new SoupXAmbient.Entry(0,0,9007199254740991L),new SoupXAmbient.Entry(1,0,1)),budget()));assertThrows(IllegalStateException.class,()->new SoupXAmbient.Counts(List.of("g"),List.of("c"),List.of(),new SoupXAmbient.Budget(1)));}
    @Test void retainsEmptyProfileAndRefusesItsUseForManualEstimation(){var x=new SoupXAmbient.Counts(List.of("g"),List.of("c"),List.of(new SoupXAmbient.Entry(0,0,2)),budget());var profile=SoupXAmbient.profile(x,2,3,budget());assertEquals(0,profile.total());assertTrue(Double.isNaN(profile.fractions().get(0)));assertThrows(IllegalArgumentException.class,()->SoupXAmbient.nonExpressing(x,profile,Map.of("set",List.of("g")),null,1,.05,100,budget()));}
    @Test void manualMaskRequiresAcceptedCellsAndLiteralAxisOrder(){var x=new SoupXAmbient.Counts(List.of("g"),List.of("c"),List.of(new SoupXAmbient.Entry(0,0,2)),budget());var p=SoupXAmbient.profile(x,0,3,budget());assertThrows(IllegalArgumentException.class,()->SoupXAmbient.globalPoisson(x,p,Map.of("set",List.of("g")),new SoupXAmbient.Mask(List.of("c"),List.of("set"),List.of(List.of(false)),List.of()),budget()));assertThrows(IllegalArgumentException.class,()->SoupXAmbient.globalPoisson(x,p,Map.of("set",List.of("g")),new SoupXAmbient.Mask(List.of("other"),List.of("set"),List.of(List.of(true)),List.of()),budget()));}
}
